{
  "items": [
    {
      "name": "MvPowerSeries.constantCoeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R),\n      MvPowerSeries.constantCoeff (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • MvPowerSeries.constantCoeff (d.prod fun s e => a s ^ e)"
    },
    {
      "name": "MvPowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • (MvPowerSeries.coeff e) (d.prod fun s e => a s ^ e)"
    },
    {
      "name": "PowerSeries.coeff_subst'",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S] {b : PowerSeries S},\n  PowerSeries.HasSubst b →\n    ∀ (f : PowerSeries R) (e : ℕ),\n      (PowerSeries.coeff e) (PowerSeries.subst b f) =\n        ∑ᶠ (d : ℕ), (PowerSeries.coeff d) f • (PowerSeries.coeff e) (b ^ d)"
    },
    {
      "name": "Polynomial.coeff_le_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {p : Polynomial F} {f : F →+* K} {B : ℝ}\n  (i : ℕ),\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n        ‖(Polynomial.map f p).coeff i‖ ≤ B ^ (p.natDegree - i) * ↑(p.natDegree.choose i)"
    },
    {
      "name": "PowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {τ : Type u_3} {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  {a : MvPowerSeries τ S},\n  PowerSeries.HasSubst a →\n    ∀ (f : PowerSeries R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (PowerSeries.subst a f) =\n        ∑ᶠ (d : ℕ), (PowerSeries.coeff d) f • (MvPowerSeries.coeff e) (a ^ d)"
    }
  ]
}
